def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    mod = 1_000_000_007
    k = len(alphabet)
    index = {ch: i for i, ch in enumerate(alphabet)}

    children = [[-1] * k]
    terminal = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = index[ch]
            if children[node][c] == -1:
                children[node][c] = len(children)
                children.append([-1] * k)
                terminal.append(False)
            node = children[node][c]
        terminal[node] = True

    failure = [0] * len(children)
    queue = []

    for c in range(k):
        child = children[0][c]
        if child == -1:
            children[0][c] = 0
        else:
            queue.append(child)

    pos = 0
    while pos < len(queue):
        node = queue[pos]
        pos += 1
        terminal[node] |= terminal[failure[node]]

        for c in range(k):
            child = children[node][c]
            if child == -1:
                children[node][c] = children[failure[node]][c]
            else:
                failure[child] = children[failure[node]][c]
                queue.append(child)

    safe = [node for node in range(len(children)) if not terminal[node]]
    state_index = {node: i for i, node in enumerate(safe)}
    size = len(safe)

    matrix = [[0] * size for _ in range(size)]
    for node in safe:
        i = state_index[node]
        for dest in children[node]:
            if not terminal[dest]:
                matrix[i][state_index[dest]] += 1

    vector = [0] * size
    vector[state_index[0]] = 1

    while n:
        if n & 1:
            result = [0] * size
            for i, value in enumerate(vector):
                if value:
                    for j, count in enumerate(matrix[i]):
                        result[j] = (result[j] + value * count) % mod
            vector = result

        n >>= 1
        if n:
            squared = [[0] * size for _ in range(size)]
            for i in range(size):
                for j, value in enumerate(matrix[i]):
                    if value:
                        for h, count in enumerate(matrix[j]):
                            squared[i][h] = (squared[i][h] + value * count) % mod
            matrix = squared

    return sum(vector) % mod
